import { InstanceId, VariantName, VesselId, tilingLeafToken } from '@maelstrom-co/protocol';
import { createMaelstrom, defineVessel, vessel } from '@maelstrom-co/react';
import { useState, type FormEvent } from 'react';
import type { EngineConnector } from '@maelstrom-co/client';

const tickets = [
  { id: 'T-104', subject: 'Cannot update billing address', status: 'Open' },
  { id: 'T-105', subject: 'Export is missing a column', status: 'Waiting' },
] as const;

const queueVessel = defineVessel({
  id: 'support-queue',
  name: 'Support queue',
  description: 'The current support queue with its ticket subjects and statuses.',
  defaultVariant: 'queue',
  variants: {
    queue: {
      description: 'The support ticket queue.',
      props: { tickets },
      minSize: { width: 3, height: 2 },
      actions: [],
    },
  },
});

const SupportQueue = ({ variantProps }: { variantProps: { variant: 'queue'; tickets: typeof tickets } }) => (
  <ul>
    {variantProps.tickets.map((ticket) => (
      <li key={ticket.id}>
        <strong>{ticket.subject}</strong> — {ticket.status}
      </li>
    ))}
  </ul>
);

const supportQueue = vessel(queueVessel, SupportQueue);
const maelstrom = createMaelstrom({ vessels: [supportQueue] });
const initialLayout = {
  type: 'tiling' as const,
  tree: [tilingLeafToken(InstanceId('support-queue-instance'))],
  instances: [
    {
      instanceId: InstanceId('support-queue-instance'),
      vesselId: VesselId('support-queue'),
      variant: VariantName('queue'),
    },
  ],
};

function QueueIntent() {
  const { processIntent, isProcessing, lastError } = maelstrom.useMaelstrom();
  const [message, setMessage] = useState('');

  function submitIntent(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const intent = message.trim();
    if (!intent || isProcessing) return;
    void processIntent(intent);
  }

  return (
    <>
      <form onSubmit={submitIntent}>
        <label>
          Ask Maelstrom to arrange the support queue
          <input
            value={message}
            onChange={(event) => setMessage(event.target.value)}
            placeholder="e.g. Show the support queue"
          />
        </label>
        <button type="submit" disabled={isProcessing || !message.trim()}>
          {isProcessing ? 'Arranging…' : 'Arrange queue'}
        </button>
      </form>
      {lastError && <p role="alert">Maelstrom could not arrange the queue: {lastError.message}</p>}
      <maelstrom.Chart />
    </>
  );
}

export function App({ connector }: { connector?: EngineConnector }) {
  return (
    <main>
      <h1>Support workspace</h1>
      <p>Review the open support queue.</p>
      {connector ? (
        <maelstrom.Provider connector={connector} initialLayout={initialLayout}>
          <QueueIntent />
        </maelstrom.Provider>
      ) : (
        <>
          <ul>
            {tickets.map((ticket) => (
              <li key={ticket.id}>
                <strong>{ticket.subject}</strong> — {ticket.status}
              </li>
            ))}
          </ul>
          <p role="status">Configure VITE_MAELSTROM_API_URL to enable Maelstrom queue selection.</p>
        </>
      )}
    </main>
  );
}

