import { HttpConnector } from '@maelstrom-co/react';
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';

const root = document.getElementById('root');
if (!root) throw new Error('Missing #root');

const apiBaseUrl = import.meta.env.VITE_MAELSTROM_API_URL;
const connector = apiBaseUrl ? new HttpConnector({ baseUrl: apiBaseUrl }) : undefined;

createRoot(root).render(
  <StrictMode>
    <App connector={connector} />
  </StrictMode>,
);

