// @vitest-environment jsdom
import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import type { ChartRequestMessage } from '@maelstrom-co/protocol';
import type { EngineConnector } from '@maelstrom-co/client';
import { describe, expect, it } from 'vitest';
import { createSimulatedConnector } from './testConnector';
import { App } from './App';

describe('support queue Vessel', () => {
  it('preserves the queue and submits the user intent through Maelstrom', async () => {
    const simulated = createSimulatedConnector();
    const requests: ChartRequestMessage[] = [];
    const connector: EngineConnector = {
      ...simulated,
      async process(message) {
        requests.push(message);
        return simulated.process(message);
      },
    };

    render(<App connector={connector} />);

    expect(screen.getByRole('heading', { name: 'Support workspace' })).toBeTruthy();
    expect(screen.getByText('Review the open support queue.')).toBeTruthy();
    expect(screen.getByText('Cannot update billing address')).toBeTruthy();
    expect(screen.getByText('Export is missing a column')).toBeTruthy();

    fireEvent.change(screen.getByLabelText('Ask Maelstrom to arrange the support queue'), {
      target: { value: 'Show the support queue' },
    });
    fireEvent.click(screen.getByRole('button', { name: 'Arrange queue' }));

    await waitFor(() => {
      expect(
        requests.some((request) =>
          request.request.context.updateReasons.some(
            (reason) => reason.type === 'user_intent' && reason.intent === 'Show the support queue',
          ),
        ),
      ).toBe(true);
    });
  });
});

